operation.document:
query GetInitiativesPage($filter: InitiativeFilter, $includeArchived: Boolean, $after: String) {
  initiatives(filter: $filter, includeArchived: $includeArchived, after: $after) {
    nodes { id slugId name description status targetDate health color icon url archivedAt
      owner { id displayName initials }
      projects { nodes { id name status { name } } }
    }
    pageInfo { hasNextPage endCursor }
  }
}
